const stages: (Stage|'All')[] = ['All','New','Attempted','Qualification','Qualified','Lost']
const stageFilterLabel: Record<Stage|'All', string> = { All:'All lead buckets', New:'New', Attempted:'Follow-up', Contacted:'Interested', Qualification:'Interested', Qualified:'Sent to Sales', Nurture:'Interested', Lost:'Dead' }
const sources: (Source|'All')[] = ['All','Website','Phone','Referral','Campaign','Walk-in','Partner']
const createSchema = z.object({ name:z.string().min(2,'Customer name is required'),email:z.email('Enter a valid email'),phone:z.string().min(10,'Enter a valid phone number'),city:z.string().min(2,'Location is required'),type:z.enum(['Individual','Group / Community']),source:z.enum(['Website','Phone','Referral','Campaign','Walk-in','Partner']),requirement:z.string().min(5,'Describe the requirement'),budget:z.string().min(2,'Budget is required'),timeline:z.string().min(2,'Timeline is required'),landStatus:z.string().min(2,'Land status is required'),priority:z.enum(['High','Medium','Low'])})
type CreateInput=z.infer<typeof createSchema>
const leadColumnHelper=createColumnHelper<Lead>()

function matchesLeadFocus(lead: Lead, focus: string, followUps: FollowUp[]) {
  if (focus === 'open-follow-ups') return followUps.some(item => item.journeyId === lead.journeyId && item.status === 'Open')
  if (focus === 'qualification-blockers') return ['Contacted', 'Qualification'].includes(lead.stage) && qualificationMissing(lead.qualification).length > 0
  if (focus === 'new-leads') return lead.stage === 'New'
  if (focus === 'follow-up-leads') return ['RNR', 'Call Back Later', 'Switch Off'].includes(lead.lastDisposition ?? '')
  if (focus === 'interested-leads') return lead.lastDisposition === 'Interested' && lead.stage !== 'Qualified'
  if (focus === 'dead-leads') return lead.lastDisposition === 'Not Interested' || lead.stage === 'Lost'
  return true
}

function matchesStageFilter(lead: Lead, stage: Stage|'All') {
  if (stage === 'All') return true
  if (stage === 'Qualification') return ['Contacted','Qualification','Nurture'].includes(lead.stage)
  return lead.stage === stage
}

